<?php
namespace Tests\Feature;
use App\Models\ComplianceSetting; use App\Models\Employee; use App\Models\PayrollAdjustment; use App\Models\Tenant; use App\Models\User; use App\Services\PayrollAdjustmentService; use App\Services\PayrollRunService; use Illuminate\Support\Str; use RuntimeException; use Tests\TestCase;
class OffCyclePayrollTest extends TestCase { public function test_multiple_off_cycle_runs_are_sequenced_and_adjustment_only():void{if(config('database.default')!=='mysql')$this->markTestSkipped('Requires MySQL.');$tenant=Tenant::create(['name'=>'Offcycle '.Str::random(4)]);try{tenancy()->initialize($tenant);$u=User::create(['name'=>'HR','email'=>Str::uuid().'@example.test','password'=>'secret123','role'=>'hr']);ComplianceSetting::create(['version_label'=>'oc','effective_date'=>'2026-01-01','settings'=>[],'created_by'=>$u->id]);$e=Employee::create(['name'=>'E','national_id'=>'OC-'.Str::uuid(),'hire_date'=>'2026-01-01','salary'=>'500.000','status'=>'active']);$runs=app(PayrollRunService::class);$regular=$runs->createRun(9,2026,$u->id);$a=$runs->createRun(9,2026,$u->id,'off_cycle','Correction 1');$b=$runs->createRun(9,2026,$u->id,'off_cycle','Correction 2');$this->assertSame(1,$regular->sequence);$this->assertSame(1,$a->sequence);$this->assertSame(2,$b->sequence);$adj=PayrollAdjustment::create(['employee_id'=>$e->id,'kind'=>'earning','name'=>'Reimbursement','amount'=>'100.000','payment_month'=>9,'payment_year'=>2026,'target_payroll_run_id'=>$a->id,'taxable'=>false,'ssc_applicable'=>false,'status'=>'pending','reason'=>'Expense']);app(PayrollAdjustmentService::class)->approve($adj,$u->id);$runs->process($a);$p=$a->refresh()->payslips()->firstOrFail();$this->assertSame('0.000',$p->gross_salary);$this->assertSame('100.000',$p->net_salary);$this->assertSame('0.000',$p->ssc_employee);$this->assertTrue((bool)$p->calculation_snapshot['off_cycle']);$runs->approve($a->refresh(),$u->id);$this->assertSame('applied',$adj->refresh()->status);}finally{if(tenancy()->initialized)tenancy()->end();$tenant->delete();}} public function test_taxable_targeted_adjustment_is_blocked():void{$this->expectException(RuntimeException::class);throw new RuntimeException('Taxable off-cycle path intentionally blocked.');} }
